mapper.insert:
INSERT INTO booking_lock (
    member_id, room_id, check_in, check_out, guest_name, phone, guest_count, remark,
    room_amount, discount_amount, points_used, amount, status, expires_at
) VALUES (
    #{memberId}, #{roomId}, #{checkIn}, #{checkOut}, #{guestName}, #{phone}, #{guestCount}, #{remark},
    #{roomAmount}, #{discountAmount}, #{pointsUsed}, #{amount}, #{status}, #{expiresAt}
)

mapper.select:
SELECT COALESCE(SUM(points_used), 0)
FROM booking_lock
WHERE member_id = #{memberId}
  AND status = 'PENDING'
  AND expires_at > #{now}
